          len = Math.hypot(...axis);
        if (len < 0.001) return;
        axis = axis.map(v => v / len);
        let x = V.norm(V.cross(axis, Math.abs(axis[2]) > 0.95 ? [1, 0, 0] : [0, 0, 1])),
          z = V.cross(x, axis);
