          g.vertexAttribDivisor(6, 1);
          g.enableVertexAttribArray(7);
          g.vertexAttribPointer(7, 1, g.FLOAT, false, 88, 80);
          g.vertexAttribDivisor(7, 1);
          g.enableVertexAttribArray(9);
          g.vertexAttribPointer(9, 1, g.FLOAT, false, 88, 84);
